using System;using System.IO;using System.Drawing;using System.Drawing.Printing;using System.Reflection;using System.Windows.Forms;using EanEtikety;
class PrintFixTests {
 static string dir;static T Field<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}static void Check(bool v,string s){if(!v)throw new Exception(s);}static void Snap(Form f,string n){Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(dir,n+".png"));}}
 [STAThread]static void Main(string[] args){dir=Path.GetFullPath(args[0]);Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Run();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS: separate window; editor retained; long printer name; preview uses PrintPage; controller restored; zoom unchanged geometry; cancellation; unavailable printer; multi-page preview and Microsoft Print to PDF. No physical job sent.");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
 static void Run(){using(var editor=new MainForm(Path.Combine(dir,"startup.xml"))){editor.StartPosition=FormStartPosition.Manual;editor.Location=new Point(-20000,-20000);editor.Show();var original=(LabelSettings)Call(editor,"Read");var s=LabelSettings.Default();s.UsePaper=true;s.PageWidth=210;s.PageHeight=297;s.MarginX=12;s.MarginY=15;s.Copies=2;
 using(var window=(Form)Call(editor,"CreatePrintWindow",s)){window.StartPosition=FormStartPosition.Manual;window.Location=new Point(-20000,-20000);window.Show();Check(editor.Controls[0].Visible,"editor remains visible");var panel=(PrintPanel)window.Controls[0];Check(panel.Parent==window&&window!=editor,"separate form");var doc=Field<LabelPrintDocument>(panel,"document");var canvas=Field<PrintCanvas>(panel,"preview");int generated=0;doc.PrintPage+=delegate{generated++;};var controller=doc.PrintController;panel.RefreshPreview();Check(generated==2,"preview invokes print page for each page");Check(doc.PrintController==controller,"restored controller");var pages=Field<PreviewPageInfo[]>(canvas,"pages");Check(pages.Length==2,"all preview pages");
 string longName="\\\\server-very-long-print-location\\Department-Production-North-Floor-3-Label-Printer-Unit-123456789";var printers=Field<ModernComboBox>(panel,"printers");printers.Items.Add(longName);printers.SelectedItem=longName;Check(Field<Label>(panel,"printerName").Text==longName,"full name retained");Check(!Field<ModernButton>(panel,"print").Enabled,"invalid printer disabled");Snap(window,"long-name");
 string pdf=null;foreach(string name in PrinterSettings.InstalledPrinters)if(name=="Microsoft Print to PDF")pdf=name;Check(pdf!=null,"PDF driver installed");printers.SelectedItem=pdf;Check(doc.DefaultPageSettings.PaperSize.RawKind==new PrinterSettings{PrinterName=pdf}.DefaultPageSettings.PaperSize.RawKind,"printer default paper loaded");var paperList=Field<ModernComboBox>(panel,"papers");for(int i=0;i<paperList.Items.Count;i++)if(((PaperSize)paperList.Items[i]).Kind==PaperKind.A5){paperList.SelectedIndex=i;break;}Check(canvas.Paper.Width>140&&canvas.Paper.Width<150,"A5 preview uses printer paper");foreach(PaperSize size in doc.PrinterSettings.PaperSizes)if(size.Kind==PaperKind.A4){doc.DefaultPageSettings.PaperSize=size;break;}panel.RefreshPreview();var paper=canvas.Paper;var bounds=doc.LabelBounds(0);Field<ModernComboBox>(panel,"zoom").SelectedIndex=4;Check(doc.LabelBounds(0)==bounds&&canvas.Paper==paper,"zoom no print scaling");Field<ModernComboBox>(panel,"zoom").SelectedIndex=0;
 Check(!panel.ConfigurePrinter(d=>{doc.DefaultPageSettings.Landscape=true;doc.PrinterSettings.Copies=7;return DialogResult.Cancel;}),"cancel result");Check(!doc.DefaultPageSettings.Landscape&&doc.PrinterSettings.Copies==1,"cancel restored");
 Snap(window,"preview-dark");window.Size=window.MinimumSize;Snap(window,"preview-minimum");pages=Field<PreviewPageInfo[]>(canvas,"pages");using(var bmp=new Bitmap(827,1170))using(var g=Graphics.FromImage(bmp)){g.Clear(Color.White);g.DrawImage(pages[0].Image,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(Path.Combine(dir,"preview-page.png"));}
 doc.PrinterSettings.Copies=1;doc.PrinterSettings.PrintToFile=true;doc.PrinterSettings.PrintFileName=Path.Combine(dir,"windows-print.pdf");panel.SendToPrinter(d=>{Check(d.PrinterSettings.PrinterName==pdf,"virtual printer only");d.PrintController=new StandardPrintController();d.Print();});Check(!Field<Label>(panel,"info").Text.Contains("nepodarila"),"PDF success");Call(panel,"Back");Check(window.IsDisposed,"back closes print window");}
 Check(((LabelSettings)Call(editor,"Read")).Ean==original.Ean,"editor retained after close");editor.Close();}}
}

